window.STUDIA_CARDS=[{"id": "praca/cwiczenia-1-fiszki:bd7f026d", "q": "Jak Hofstede definiuje kulturę i skąd się ona bierze?", "a": "<p>Kultura to <strong>kolektywne zaprogramowanie umysłu, które odróżnia członków jednej grupy lub kategorii ludzi od drugiej</strong>. Jest wyuczona, nie dziedziczona; jej źródłem jest środowisko społeczne (rodzina, szkoła, rówieśnicy, praca). Najwięcej przyswajamy we wczesnym dzieciństwie. Zaprogramowanie wskazuje reakcje prawdopodobne, ale nie determinuje zachowania w pełni.</p>", "src": "Hofstede, rozdz. 1", "k": ["kolektywne zaprogramowanie umysłu", "odróżnia grupy i kategorie", "wyuczona, nie dziedziczona", "nie determinuje w pełni"], "u": "cwiczenia-1.html", "s": "s1"}, {"id": "praca/cwiczenia-1-fiszki:52ca8a53", "q": "Czym różni się kultura numer jeden od kultury numer dwa?", "a": "<p><strong>Kultura numer jeden</strong> to wąskie znaczenie: cywilizacja, wyrafinowanie intelektualne, sztuka, literatura, wykształcenie. <strong>Kultura numer dwa</strong> to znaczenie antropologiczne: całe zaprogramowanie umysłu, łącznie z codziennymi zachowaniami – pozdrawianiem, okazywaniem uczuć, jedzeniem, dystansem fizycznym, higieną. Książka dotyczy kultury numer dwa.</p>", "src": "Hofstede, rozdz. 1", "k": ["nr 1: sztuka, wykształcenie", "nr 2: znaczenie antropologiczne", "codzienne zachowania"], "u": "cwiczenia-1.html", "s": "s1"}, {"id": "praca/cwiczenia-1-fiszki:187cd717", "q": "Jakie są trzy poziomy zaprogramowania umysłu i skąd pochodzi każdy z nich?", "a": "<p><strong>Natura ludzka</strong> – uniwersalna, dziedziczona („system operacyjny”: zdolność odczuwania emocji, potrzeba przynależności). <strong>Kultura</strong> – specyficzna dla grupy lub kategorii, nabyta (m.in. to, jak wyrażamy emocje). <strong>Osobowość</strong> – specyficzna dla jednostki, dziedziczona i nabyta.</p>", "src": "Hofstede, rozdz. 1", "k": ["natura ludzka: uniwersalna, dziedziczona", "kultura: grupowa, nabyta", "osobowość: indywidualna, dziedziczona i nabyta"], "u": "cwiczenia-1.html", "s": "s1"}, {"id": "praca/cwiczenia-1-fiszki:ac33fc77", "q": "Na czym polega relatywizm kulturowy?", "a": "<p>Nie istnieje obiektywne kryterium uznawania jednej kultury za wyższą lub niższą od innej (Lévi-Strauss). Relatywizm nie oznacza braku zasad dla siebie, ale wymaga powstrzymania się od pochopnych ocen innych grup i przyjrzenia się istocie różnic, ich źródłom i konsekwencjom.</p>", "src": "Hofstede, rozdz. 1", "k": ["brak kryterium wyższości", "nie oznacza braku własnych zasad", "powstrzymanie od ocen", "badanie źródeł różnic"], "u": "cwiczenia-1.html", "s": "s2"}, {"id": "praca/cwiczenia-1-fiszki:1eb132f2", "q": "Co przedstawia „diagram cebuli” Hofstedego?", "a": "<p>Przejawy kultury na różnych głębokościach: na zewnątrz <strong>symbole</strong> (słowa, gesty, ubiór, flagi – zmieniają się najszybciej), głębiej <strong>bohaterowie</strong> (wzorce zachowań, realni lub fikcyjni) i <strong>rytuały</strong> (zbiorowe działania zbędne technicznie, ale społecznie niezbędne), w rdzeniu <strong>wartości</strong>. Symbole, bohaterowie i rytuały to razem <strong>praktyki</strong> – widoczne, ale ich znaczenie czytają tylko członkowie kultury.</p>", "src": "Hofstede, rozdz. 1", "k": ["symbole – zewnętrzne", "bohaterowie, rytuały", "wartości – rdzeń", "praktyki = symbole + bohaterowie + rytuały"], "u": "cwiczenia-1.html", "s": "s2"}, {"id": "praca/cwiczenia-1-fiszki:7444c4c9", "q": "Czym są wartości według Hofstedego i jak się je bada?", "a": "<p>Wartości to skłonność do preferowania pewnego stanu rzeczy – uczucia z biegunem dodatnim i ujemnym (dobry–zły, czysty–brudny). Przyswajamy je najwcześniej i nieświadomie, w pierwszych 10 latach życia, potem trudno je zmienić. Nie widać ich wprost – wnioskuje się z zachowań. W ankietach trzeba odróżniać to, co <strong>pożądane</strong> (norma absolutna, ideologia), od tego, co <strong>pragnione</strong> (norma statystyczna, rzeczywiste wybory).</p>", "src": "Hofstede, rozdz. 1", "k": ["preferowanie stanu rzeczy", "pierwsze 10 lat życia", "pożądane vs pragnione", "norma absolutna vs statystyczna"], "u": "cwiczenia-1.html", "s": "s2"}, {"id": "praca/cwiczenia-1-fiszki:eca042c7", "q": "Jakie warstwy kultury nosi w sobie każdy człowiek?", "a": "<p>Narodową; regionalną, etniczną, religijną lub językową; płci; pokoleniową; klasy społecznej; organizacyjną lub korporacyjną. Warstwy mogą być ze sobą sprzeczne, co utrudnia przewidywanie zachowania w nowej sytuacji.</p>", "src": "Hofstede, rozdz. 1", "k": ["narodowa, regionalna/etniczna", "płeć, pokolenie", "klasa społeczna", "organizacyjna"], "u": "cwiczenia-1.html", "s": "s2"}, {"id": "praca/cwiczenia-1-fiszki:55ceb721", "q": "Jakie wymiary kultur narodowych wyodrębnił Hofstede i na jakich danych?", "a": "<p>Na danych ankietowych pracowników <strong>IBM</strong> z ponad 50 krajów: <strong>dystans władzy</strong>, <strong>indywidualizm–kolektywizm</strong>, <strong>męskość–kobiecość</strong>, <strong>unikanie niepewności</strong>. Wyniki były zbieżne z problemami uniwersalnymi Inkelesa i Levinsona. Piąty wymiar – <strong>orientację długo- i krótkoterminową</strong> – odkrył Michael Bond ankietą ułożoną przez chińskich badaczy.</p>", "src": "Hofstede, rozdz. 1", "k": ["IBM, ponad 50 krajów", "dystans władzy, indywidualizm", "męskość, unikanie niepewności", "5. wymiar: Bond"], "u": "cwiczenia-1.html", "s": "s3"}, {"id": "praca/cwiczenia-1-fiszki:cd3e02df", "q": "Czym różni się model wymiarowy od typologii?", "a": "<p><strong>Typologia</strong> opisuje typy idealne, łatwe do wyobrażenia i przydatne dydaktycznie, ale konkretny przypadek rzadko do nich pasuje. <strong>Model wymiarowy</strong> pozwala jednoznacznie umieścić każdy przypadek na skali; lepszy w badaniach. Z wymiarów można ex post utworzyć typologię empiryczną (13 grup krajów z danych IBM).</p>", "src": "Hofstede, rozdz. 1", "k": ["typologia: typy idealne", "dydaktyka", "wymiary: jednoznaczne umiejscowienie", "badania"], "u": "cwiczenia-1.html", "s": "s3"}, {"id": "praca/cwiczenia-1-fiszki:48b3f089", "q": "Czym kultura organizacyjna różni się od narodowej według Hofstedego?", "a": "<p>Członkostwo w organizacji jest częściowo <strong>dobrowolne</strong>, ograniczone do czasu pracy i można z niego zrezygnować. Wymiary narodowe są tu przydatne tylko częściowo; kultury organizacyjne Hofstede badał osobno (projekt IRIC w Danii i Holandii). Wniosek Hofstedego: narody różnią się głównie wartościami, organizacje – praktykami.</p>", "src": "Hofstede, rozdz. 1", "k": ["członkostwo dobrowolne", "ograniczone w czasie", "IRIC", "organizacje różnią się praktykami"], "u": "cwiczenia-1.html", "s": "s3"}, {"id": "praca/cwiczenia-1-fiszki:18ce508f", "q": "Czym różni się kultura organizacyjna od klimatu organizacyjnego?", "a": "<p>Według Grzywacza kultura jest <strong>głęboka, podświadoma, abstrakcyjna, zbiorowa</strong>, istnieje przez symbole, historie i mity, które spajają organizację. Klimat jest <strong>powierzchowny, świadomy, konkretny, indywidualny</strong> – to sposób postrzegania przez pracownika dążeń, procedur i wzorów zachowań. Klimat nie jest ani synonimem, ani antonimem kultury, tylko jednym z jej składników.</p>", "src": "Lipińska-Grobelny", "k": ["kultura: głęboka, podświadoma, zbiorowa", "klimat: powierzchowny, świadomy, indywidualny", "klimat = składnik kultury"], "u": "cwiczenia-1.html", "s": "s4"}, {"id": "praca/cwiczenia-1-fiszki:e961fe04", "q": "Jak klimat organizacyjny definiują Kolb, Borucki i Paluchowski?", "a": "<p><strong>Kolb</strong>: zbiór subiektywnie spostrzeganych cech sytuacji, które kształtują motywy zachowań. <strong>Borucki</strong>: indywidualna mapa percepcyjno-poznawcza sytuacji organizacyjnej. <strong>Paluchowski</strong>: zespół zjawisk kształtowanych przez czynniki rynkowe (zewnętrzne) oraz kulturowe i organizacyjne (wewnętrzne), które blokują lub ułatwiają działania pracowników.</p>", "src": "Lipińska-Grobelny", "k": ["Kolb: subiektywne cechy sytuacji", "Borucki: mapa percepcyjno-poznawcza", "Paluchowski: blokuje lub ułatwia działania"], "u": "cwiczenia-1.html", "s": "s4"}, {"id": "praca/cwiczenia-1-fiszki:70083502", "q": "Jakie klimaty wyróżnił Dobrzyński i od czego one zależą?", "a": "<p>Klimat zależy od <strong>dominującej potrzeby</strong>, kształtowanej przez bodźce stosowane przez kierownika: potrzeba bezpieczeństwa – klimat <strong>biurokratyczny</strong>, potrzeba władzy kadry – <strong>autorytarny</strong>, potrzeba osiągnięć – <strong>innowacyjny</strong>, potrzeba afiliacji – <strong>towarzyski</strong>.</p>", "src": "Lipińska-Grobelny", "k": ["bezpieczeństwo → biurokratyczny", "władza → autorytarny", "osiągnięcia → innowacyjny", "afiliacja → towarzyski"], "u": "cwiczenia-1.html", "s": "s5"}, {"id": "praca/cwiczenia-1-fiszki:9b62a642", "q": "Jak wymiary Hofstedego przekładają się na organizację?", "a": "<p><strong>Dystans władzy</strong>: na ile pracownicy akceptują formalną hierarchię. <strong>Indywidualizm–kolektywizm</strong>: przewaga interesów jednostki czy grupy. <strong>Męskość–kobiecość</strong>: wartości ekonomiczne (awans, płaca, sukces) czy społeczne (atmosfera, zaufanie, opieka). <strong>Unikanie niepewności</strong>: gotowość działania przy zmianach i bez procedur. <strong>Konfucjański dynamizm</strong>: orientacja długoterminowa (upór, oszczędność, relacje według statusu) czy krótkoterminowa (zachowanie twarzy, tradycja, zobowiązania).</p>", "src": "Lipińska-Grobelny", "k": ["dystans: akceptacja hierarchii", "interes jednostki vs grupy", "wartości ekonomiczne vs społeczne", "długo- vs krótkoterminowa"], "u": "cwiczenia-1.html", "s": "s5"}, {"id": "praca/cwiczenia-1-fiszki:7b4159b7", "q": "Jakie cztery typy kultury organizacyjnej wyróżnia Hofstede (2000)?", "a": "<p>(a) Orientacja na <strong>stabilizację i bezpieczeństwo</strong> – sztywna struktura, indywidualizm to zagrożenie. (b) Orientacja na <strong>strukturę i rutynowe procedury</strong> – mniej formalne relacje, współdziałanie i atmosfera. (c) <strong>Wspieranie inicjatyw</strong> jednostek i małych grup – rywalizacja, zaangażowanie, twórczość. (d) Orientacja na <strong>realizację zadań</strong> – płynna struktura, przywództwo i zaangażowanie.</p>", "src": "Lipińska-Grobelny", "k": ["stabilizacja i bezpieczeństwo", "struktura i procedury", "wspieranie inicjatyw", "realizacja zadań"], "u": "cwiczenia-1.html", "s": "s5"}, {"id": "praca/cwiczenia-1-fiszki:db18c504", "q": "Jakie klimaty organizacyjne wyróżnia Kolb?", "a": "<p><strong>Wspierający</strong> (wysokie, jasne, rozwijające wymagania, osobista odpowiedzialność, dobra organizacja pracy zespołu), <strong>autokratyczny</strong> oraz <strong>pośredni</strong> między nimi.</p>", "src": "Lipińska-Grobelny", "k": ["wspierający", "autokratyczny", "pośredni"], "u": "cwiczenia-1.html", "s": "s5"}, {"id": "praca/cwiczenia-1-fiszki:272a4b59", "q": "Co wykazało badanie Lipińskiej-Grobelny i Kozanowskiej o typach organizacji i wartościach?", "a": "<p>190 pracowników niekierowniczych (Skala Wartości Rokeacha, VSM Hofstedego): wbrew Hofstedemu <strong>typ organizacji różnicuje wartości</strong> ostateczne i instrumentalne. Np. górnicy cenią bezpieczeństwo i konformizm, informatycy – dojrzałość, przyjemność i kierowanie sobą, medycy – troskę o najbliższych. Badane organizacje: silny dystans władzy, wysokie unikanie niepewności, kobiecość, indywidualizm, orientacja długoterminowa. Wniosek: istotą kultury są też wspólne wartości (zgodnie z Petersem i Watermanem).</p>", "src": "Lipińska-Grobelny", "k": ["typ organizacji różnicuje wartości", "polemika z Hofstedem", "duży dystans, wysokie unikanie niepewności", "wspólne wartości"], "u": "cwiczenia-1.html", "s": "s6"}, {"id": "praca/cwiczenia-1-fiszki:a243af5d", "q": "Co wyjaśnia „perspektywizm myślenia” Mannheima w kontekście kultury organizacyjnej?", "a": "<p>Osoby z różnych grup społecznych – tu: różnych typów organizacji – odmiennie widzą tę samą rzeczywistość. Jednostka kontynuuje sposób myślenia grupy i rozwija go lub zastępuje w nowych warunkach; dotyczy to wyjaśniania rzeczywistości, przewidywań i preferowanych systemów wartości.</p>", "src": "Lipińska-Grobelny", "k": ["różne grupy widzą inaczej", "kontynuacja sposobu myślenia grupy", "także system wartości"], "u": "cwiczenia-1.html", "s": "s6"}, {"id": "praca/cwiczenia-1-fiszki:2e54ba4b", "q": "Jak klimat organizacyjny wiąże się ze stylem władzy?", "a": "<p>Centralizacja sprzyja unikaniu niepewności i dużemu dystansowi władzy. Menedżerowie z Europy Środkowo-Wschodniej akceptują większe nierówności i skłaniają się do autorytaryzmu (Mączyński i Witkowski). Łoboda-Świątczak: jakość klimatu wyznacza styl kooperacyjny lub autokratyczny; w firmach państwowych częściej autokratyczny, zwłaszcza przy ograniczonym dostępie do informacji. Dostęp do informacji pozwala wpływać bez przymusu.</p>", "src": "Lipińska-Grobelny", "k": ["centralizacja → dystans, unikanie niepewności", "Europa Środkowo-Wschodnia: autorytaryzm", "firmy państwowe: autokratyzm", "dostęp do informacji"], "u": "cwiczenia-1.html", "s": "s7"}, {"id": "praca/cwiczenia-1-fiszki:61f685bb", "q": "Jak klimat wiąże się ze stylem komunikowania i postawą wobec zmian?", "a": "<p>Klimat <strong>wspierający</strong> (komunikacja dwustronna) sprzyja ekspresyjnemu stylowi komunikowania, <strong>autokratyczny</strong> – analitycznemu (badanie 188 handlowców). Wolan-Nowakowska: negatywna ocena pracy → postawa zachowawcza wobec zmian; kluczowe są <strong>odpowiedzialność i wsparcie społeczne</strong>. Pracownicy poinformowani o przyczynach i korzyściach fuzji mają mniej stresu.</p>", "src": "Lipińska-Grobelny", "k": ["wspierający → ekspresyjny", "autokratyczny → analityczny", "odpowiedzialność i wsparcie", "informowanie o zmianie"], "u": "cwiczenia-1.html", "s": "s7"}, {"id": "praca/cwiczenia-1-fiszki:cd281acc", "q": "Jaki jest związek klimatu organizacyjnego ze stresem roli zawodowej?", "a": "<p>Lipińska-Grobelny i Stopa (121 osób): im wyżej oceniany klimat <strong>wspierający</strong>, tym <strong>niższy stres roli</strong>; liczą się kierowanie, ciepło i poparcie, zorganizowanie i nagrody. Rozwój zawodowy (szkolenia, awans, dopasowanie warunków) zmniejsza stres, zwłaszcza wynikający z wieloznaczności roli.</p>", "src": "Lipińska-Grobelny", "k": ["wspierający klimat → mniej stresu", "ciepło, poparcie, nagrody", "rozwój zawodowy obniża stres"], "u": "cwiczenia-1.html", "s": "s7"}, {"id": "praca/cwiczenia-1-fiszki:2bb478ef", "q": "Jakie wnioski dla budowania marki organizacji płyną z rozdziału Lipińskiej-Grobelny?", "a": "<p>(1) Znajomość wartości pracowników pomaga sformułować <strong>misję</strong> i filozofię firmy. (2) Służy <strong>kierowaniu zmianą kulturową</strong> w stronę kultury proefektywnościowej. (3) Potrzebna jest <strong>demokratyzacja komunikacji</strong> – jawność zamiast ograniczania informacji. (4) <strong>Klimat</strong> decyduje o wdrażaniu nowości – odpowiedzialność i rozwój motywują i budują organizację uczącą się.</p>", "src": "Lipińska-Grobelny", "k": ["misja z wartości pracowników", "kierowanie zmianą kulturową", "demokratyzacja komunikacji", "klimat a zmiany, organizacja ucząca się"], "u": "cwiczenia-1.html", "s": "s8"}, {"id": "praca/cwiczenia-1-fiszki:22f0bc43", "q": "Jak Schein definiuje kulturę organizacyjną i jakie wyróżnia jej poziomy?", "a": "<p>Kultura to <strong>wzorzec podstawowych założeń</strong>, wypracowanych przez grupę przy rozwiązywaniu problemów <strong>zewnętrznej adaptacji i wewnętrznej integracji</strong>, działających na tyle dobrze, by przekazywać je nowym członkom. Poziomy: <strong>podstawowe założenia</strong> (rdzeń: egzystencja, natura ludzka, prawda), <strong>normy i wartości</strong> (poglądy, postawy), <strong>artefakty</strong> (struktura, procedury, zachowania, rytuały, mity).</p>", "src": "Kożusznik, rozdz. 10", "k": ["wzorzec podstawowych założeń", "adaptacja zewnętrzna i integracja wewnętrzna", "założenia → normy i wartości → artefakty"], "u": "cwiczenia-1.html", "s": "s9"}, {"id": "praca/cwiczenia-1-fiszki:422633c4", "q": "Jakie elementy kultury organizacyjnej wymienia Kożusznik?", "a": "<p><strong>Symbole</strong> (żargon, ubiór, logo), <strong>mity</strong> (ubarwione wydarzenia z przeszłości, rola wychowawcza), <strong>rytuały</strong> (powitania, ceremonie, negocjacje), <strong>wartości</strong> (przekonania o cenionym zachowaniu) i <strong>normy</strong> (praktyczna realizacja wartości). Pojęcie kultury organizacyjnej wprowadził Pettigrew (1979).</p>", "src": "Kożusznik, rozdz. 10", "k": ["symbole, mity, rytuały", "wartości, normy", "Pettigrew 1979"], "u": "cwiczenia-1.html", "s": "s9"}, {"id": "praca/cwiczenia-1-fiszki:79fd2e27", "q": "Jakie cztery typy kultury wyróżnia Handy?", "a": "<p><strong>Władzy</strong> – centralna postać założyciela, szybka reakcja, ryzyko upadku po jego odejściu. <strong>Roli</strong> – biurokratyczna „grecka świątynia” z wyspecjalizowanymi działami, liczy się stanowisko. <strong>Zadania</strong> – praca projektowa, struktura sieci, liczy się specjalizacja. <strong>Jednostki</strong> – osoba w centrum, partnerstwa specjalistów, kontrola tylko za zgodą.</p>", "src": "Kożusznik, rozdz. 10", "k": ["władzy: centralna postać", "roli: grecka świątynia", "zadania: sieć, projekty", "jednostki: partnerstwa"], "u": "cwiczenia-1.html", "s": "s9"}, {"id": "praca/cwiczenia-1-fiszki:4e74ebc6", "q": "Jakie cztery klimaty organizacyjne wyróżnia Dobrzyński i który układ jest optymalny?", "a": "<p><strong>Autorytarny</strong> (presja władzy, mistrz i lojalny uczeń), <strong>biurokratyczny</strong> (reguły, formalizacja, asekuracja), <strong>towarzyski</strong> (dobre stosunki, cele drugorzędne), <strong>innowacyjny</strong> (wpływ zależy od kwalifikacji, zespoły projektowe). Optymalny: <strong>innowacyjny z domieszką autorytarnego i towarzyskiego</strong>.</p>", "src": "Kożusznik, rozdz. 10", "k": ["autorytarny, biurokratyczny", "towarzyski, innowacyjny", "optimum: innowacyjny + domieszka"], "u": "cwiczenia-1.html", "s": "s10"}, {"id": "praca/cwiczenia-1-fiszki:297e9d81", "q": "Jakie wymiary obejmuje diagnoza klimatu organizacyjnego wg Kolba?", "a": "<p>Siedem wymiarów na skali 1–10, oceniane jako stan obecny (A) i idealny (I): <strong>konformizm, odpowiedzialność, wymagania (standardy), nagrody, zorganizowanie, poczucie ciepła i poparcia, kierowanie</strong>. Klimat ma źródło w teorii pola Lewina i jest „powierzchnią kultury”.</p>", "src": "Kożusznik, rozdz. 10", "k": ["konformizm, odpowiedzialność", "wymagania, nagrody", "zorganizowanie, ciepło i poparcie", "kierowanie; A vs I"], "u": "cwiczenia-1.html", "s": "s10"}, {"id": "praca/cwiczenia-1-fiszki:786243fd", "q": "Jak dystans władzy i unikanie niepewności przejawiają się w organizacji?", "a": "<p><strong>Duży dystans władzy</strong>: centralizacja, kontrola zewnętrzna, duży dystans przełożony–podwładny; mały – decentralizacja, płaskie struktury. Polscy menedżerowie najbardziej autokratyczni (Mączyński). <strong>Wysokie unikanie niepewności</strong>: przepisy, standaryzacja, eksperci, zmiany tylko planowane; niskie – mniej przepisów, akceptacja różnic, nieformalna komunikacja, zmienne struktury.</p>", "src": "Kożusznik, rozdz. 10", "k": ["duży dystans: centralizacja", "Polacy: autokratyczni", "wysokie unikanie: przepisy, standaryzacja", "niskie: elastyczność"], "u": "cwiczenia-1.html", "s": "s11"}, {"id": "praca/cwiczenia-1-fiszki:b1561132", "q": "Jakie składniki inteligencji emocjonalnej kierownika wymienia Goleman?", "a": "<p><strong>Samoświadomość</strong> (realistyczna samoocena), <strong>samoregulacja</strong> (kontrola impulsów, tolerancja niepewności), <strong>motywacja</strong> (zaangażowanie poza pieniądze i status, optymizm), <strong>empatia</strong> (rozumienie emocji innych, wrażliwość międzykulturowa), <strong>umiejętności społeczne</strong> (kierowanie zmianą, budowanie zespołów). Kompetencje społeczne kierowników zwiększają tolerancję pracowników na zmiany.</p>", "src": "Kożusznik, rozdz. 10", "k": ["samoświadomość, samoregulacja", "motywacja", "empatia", "umiejętności społeczne"], "u": "cwiczenia-1.html", "s": "s11"}, {"id": "praca/cwiczenia-1-fiszki:60629b31", "q": "Czym różnią się organizacje o wartościach męskich i kobiecych?", "a": "<p><strong>Męskie</strong>: nastawienie na karierę i rywalizację, indywidualne cele, przedsiębiorczość, raczej autokratyczny styl. <strong>Kobiece</strong>: relacje, styl partycypacyjny, słaba rywalizacja, integracja. Zbyt silne wartości męskie: ośrodki nacisku, postawa „zrób to sam”, mniejsza tolerancja, hamowanie eksperymentów i uczenia się.</p>", "src": "Kożusznik, rozdz. 10", "k": ["męskie: kariera, rywalizacja", "kobiece: relacje, partycypacja", "koszty nadmiaru męskości"], "u": "cwiczenia-1.html", "s": "s11"}, {"id": "praca/cwiczenia-1-fiszki:4b2d0b19", "q": "Jakich umiejętności potrzebuje menedżer w środowisku międzykulturowym?", "a": "<p><strong>Komunikacja dwukierunkowa</strong> (dialog), <strong>empatia</strong>, <strong>otwartość</strong>, <strong>tolerowanie niepewności</strong> i <strong>ukierunkowanie na cel</strong> z perspektywy ekwifinalności – cel można osiągnąć różnymi sposobami.</p>", "src": "Kożusznik, rozdz. 10", "k": ["komunikacja dwukierunkowa", "empatia, otwartość", "tolerancja niepewności", "ekwifinalność"], "u": "cwiczenia-1.html", "s": "s12"}, {"id": "praca/cwiczenia-1-fiszki:e015c2ed", "q": "Jak kultura wpływa na skuteczność ZPC, benchmarkingu, struktur sieciowych i kół jakości?", "a": "<p><strong>ZPC</strong> wymaga negocjacji, więc słabo działa przy dużym dystansie władzy. <strong>Benchmarking</strong> bywa trudny tam, gdzie ocena przy innych zagraża godności. <strong>Struktury sieciowe</strong> wymagają akceptacji niepewności (najłatwiej Szwedom i Holendrom). <strong>Koła jakości</strong> (dobrowolne, bottom up, 5–10 osób) w Polsce przyjmują się słabo z powodu formalnych relacji przełożony–podwładny.</p>", "src": "Kożusznik, rozdz. 10", "k": ["ZPC a dystans władzy", "benchmarking a godność", "sieci a unikanie niepewności", "koła jakości w Polsce"], "u": "cwiczenia-1.html", "s": "s12"}, {"id": "praca/cwiczenia-2-fiszki:1d478e20", "q": "Jak Schultz definiuje stres i czym są zaburzenia psychosomatyczne?", "a": "<p><strong>Stres</strong>: fizjologiczne i psychologiczne reakcje na niezwykłe, zwykle nieprzyjemne bodźce lub zagrażające wydarzenia w otoczeniu. <strong>Zaburzenia psychosomatyczne</strong>: rzeczywiste dolegliwości fizyczne wywołane czynnikami emocjonalnymi, np. stresem w pracy (wrzody, choroba wieńcowa, egzemy, alergie, bóle głowy).</p>", "src": "Schultz, rozdz. 12", "k": ["reakcje fizjologiczne i psychologiczne", "bodźce niezwykłe, zagrażające", "psychosomatyka: realne uszkodzenia", "podłoże emocjonalne"], "u": "cwiczenia-2.html", "s": "s1"}, {"id": "praca/cwiczenia-2-fiszki:391a26b6", "q": "Dlaczego kontrola nad pracą chroni przed skutkami stresu? Podaj przykłady badań.", "a": "<p>Kontrola i satysfakcja buforują stres. Dyrektorzy mają o 40% mniej zawałów niż kadra średnia (autonomia). Karasek: praca o wysokim stresie i małej kontroli → zawał 2–3 razy częściej. U kontrolerów lotów szkody pojawiają się głównie u niezadowolonych z pracy. Utrata kontroli szkodzi bardziej niż jej brak od początku.</p>", "src": "Schultz, rozdz. 12", "k": ["dyrektorzy: mniej zawałów", "Karasek: wysokie wymagania + mała kontrola", "satysfakcja chroni", "utrata kontroli najgorsza"], "u": "cwiczenia-2.html", "s": "s2"}, {"id": "praca/cwiczenia-2-fiszki:ee89d762", "q": "Czym różni się typ osobowości A od typu B i co z nim wiąże się najsilniej?", "a": "<p><strong>Typ A</strong>: rywalizacja, presja czasu, niecierpliwość, agresja, wrogość, potrzeba osiągnięć; większe ryzyko chorób serca. <strong>Typ B</strong>: może być równie ambitny, ale doświadcza mniej stresu. Metaanaliza 87 badań: z chorobami serca najsilniej wiążą się <strong>złość, wrogość i depresja</strong>. Złożona praca u typu A korelowała z chorobą wieńcową.</p>", "src": "Schultz, rozdz. 12", "k": ["A: rywalizacja, presja czasu, wrogość", "B: mniej stresu", "kluczowa wrogość i negatywne emocje", "złożona praca szkodzi typowi A"], "u": "cwiczenia-2.html", "s": "s3"}, {"id": "praca/cwiczenia-2-fiszki:20d2328a", "q": "Czym jest twardość psychiczna i jakie ma składniki?", "a": "<p>Cecha osobowości (Kobasa) wyjaśniająca różnice w odporności na stres: przekonanie o panowaniu nad wydarzeniami. Składniki: <strong>kontrola, zaangażowanie, wyzwanie</strong> (zmiana jako coś ekscytującego, nie zagrażającego). Twardzi rzadziej chorują w stresie, lepiej tolerują frustrację.</p>", "src": "Schultz, rozdz. 12", "k": ["kontrola", "zaangażowanie", "wyzwanie", "mniej dolegliwości"], "u": "cwiczenia-2.html", "s": "s3"}, {"id": "praca/cwiczenia-2-fiszki:4219da9f", "q": "Jak umiejscowienie kontroli, samoocena oparta na organizacji i negatywny afekt wpływają na stres?", "a": "<p><strong>Wewnętrzne umiejscowienie kontroli</strong> (wydarzenia zależą ode mnie) zmniejsza stres; zewnętrzne (szczęście, przypadek) go zwiększa. Wysoka <strong>samoocena oparta na organizacji</strong> (poczucie bycia odpowiednim i wartościowym w pracy) chroni. <strong>Negatywny afekt</strong> (uogólnione niezadowolenie, koncentracja na negatywach, bliski neurotyczności) zwiększa odczuwany stres.</p>", "src": "Schultz, rozdz. 12", "k": ["wewnętrzne LOC chroni", "samoocena oparta na organizacji", "negatywny afekt ~ neurotyczność", "wyższy stres"], "u": "cwiczenia-2.html", "s": "s3"}, {"id": "praca/cwiczenia-2-fiszki:357b1f9e", "q": "Jak praca i życie rodzinne wpływają na siebie i jak organizacja może pomóc?", "a": "<p>Konflikt praca–rodzina wiąże się z depresją, gorszym zdrowiem i alkoholem; zwykle praca bardziej utrudnia życie rodzinne niż odwrotnie; złe nastroje przenoszą się w obie strony. Kobiety częściej pracują na „dwa etaty”. Pomagają: <strong>elastyczna organizacja pracy i wsparcie przełożonego</strong> (więcej kontroli), opieka nad dziećmi w pracy, ruchomy czas, telepraca, niepełny etat.</p>", "src": "Schultz, rozdz. 12", "k": ["konflikt ról → depresja, zdrowie", "praca utrudnia rodzinę bardziej", "elastyczność i wsparcie szefa", "telepraca, niepełny etat"], "u": "cwiczenia-2.html", "s": "s4"}, {"id": "praca/cwiczenia-2-fiszki:93da9818", "q": "Czym różni się przeciążenie ilościowe, jakościowe i niedociążenie pracą?", "a": "<p><strong>Przeciążenie ilościowe</strong>: za dużo pracy w danym czasie (ważna kontrola nad tempem). <strong>Jakościowe</strong>: praca zbyt trudna wobec kompetencji. <strong>Niedociążenie</strong>: praca zbyt prosta, niewypełniająca czasu, niewykorzystująca kompetencji – monotonia obniża satysfakcję i zwiększa zwolnienia. Istnieje optymalny poziom stresu.</p>", "src": "Schultz, rozdz. 12", "k": ["ilościowe: za dużo", "jakościowe: za trudne", "niedociążenie: monotonia", "optymalny poziom stresu"], "u": "cwiczenia-2.html", "s": "s5"}, {"id": "praca/cwiczenia-2-fiszki:34e693db", "q": "Czym jest niejednoznaczność roli i konflikt roli?", "a": "<p><strong>Niejednoznaczność roli</strong>: obowiązki słabo ustrukturalizowane lub niezdefiniowane; składniki: niejednoznaczność kryteriów oceny, metod pracy i schematów (koordynacji zadań); szczególnie u młodych pracowników. <strong>Konflikt roli</strong>: niespójne wymagania wobec pracy albo wymagania sprzeczne z wartościami pracownika.</p>", "src": "Schultz, rozdz. 12", "k": ["niejednoznaczność: niezdefiniowane obowiązki", "kryteria, metody, schematy", "konflikt: niespójne wymagania", "lub sprzeczne z wartościami"], "u": "cwiczenia-2.html", "s": "s5"}, {"id": "praca/cwiczenia-2-fiszki:5cc8a106", "q": "Czym są masowe dolegliwości o podłożu psychologicznym?", "a": "<p>Potocznie „histeria taśmy produkcyjnej”: objawy fizyczne (zawroty głowy, nudności, duszności) gwałtownie rozprzestrzeniające się w grupie pracowników bez fizycznej przyczyny. Częściej u kobiet; wywołują je stresory fizyczne (hałas, tempo) i psychologiczne (presja, złe relacje z przełożonymi, izolacja społeczna).</p>", "src": "Schultz, rozdz. 12", "k": ["histeria taśmy produkcyjnej", "rozprzestrzeniają się w grupie", "brak przyczyny fizycznej", "presja i izolacja"], "u": "cwiczenia-2.html", "s": "s6"}, {"id": "praca/cwiczenia-2-fiszki:e9fc857f", "q": "Czym różni się zdrowy pracoholizm od niezdrowego?", "a": "<p>Pracoholizm to uzależnienie od pracy wywołane niepokojem, niepewnością lub atrakcyjnością pracy (ok. 5%). <strong>Zdrowi</strong> („entuzjaści”) są zaangażowani i czerpią dużo satysfakcji. <strong>Niezdrowi</strong> są zaangażowani bez satysfakcji, pod wewnętrznym przymusem; mają wyższy stres i gorsze zdrowie, szkodzą firmie (sztywność, nierealne standardy, problem z delegowaniem).</p>", "src": "Schultz, rozdz. 12", "k": ["zdrowi: zaangażowanie + satysfakcja", "niezdrowi: przymus, brak satysfakcji", "wyższy stres", "problem z delegowaniem"], "u": "cwiczenia-2.html", "s": "s6"}, {"id": "praca/cwiczenia-2-fiszki:45f8f0f7", "q": "Jakie działania organizacji zmniejszają stres w pracy?", "a": "<p>Kontrolowanie <strong>klimatu</strong> (udział w decyzjach przy zmianach), <strong>zapewnianie kontroli</strong> (wzbogacanie i rozszerzanie pracy), <strong>definiowanie ról</strong>, eliminowanie przeciążenia i niedociążenia (selekcja, szkolenia, podział pracy), <strong>EAP</strong> – programy wspierania pracowników, <strong>wsparcie społeczne</strong> (szczególnie przełożonych).</p>", "src": "Schultz, rozdz. 12", "k": ["klimat i udział w decyzjach", "kontrola, definiowanie ról", "eliminacja przeciążenia", "EAP, wsparcie społeczne"], "u": "cwiczenia-2.html", "s": "s7"}, {"id": "praca/cwiczenia-2-fiszki:f3d39735", "q": "Na czym polegają trening relaksacyjny, biofeedback i modyfikacja zachowań?", "a": "<p><strong>Trening relaksacyjny</strong>: koncentracja na relaksowaniu kolejnych części ciała (odmiany: trening autogenny, medytacja). <strong>Biofeedback</strong>: elektroniczne monitorowanie procesów fizjologicznych z sygnałem zwrotnym, by nauczyć się kontrolować napięcie mięśni, ciśnienie, fale mózgowe. <strong>Modyfikacja zachowań</strong>: wzmacnianie nagrodami zachowań pożądanych (np. u typu A).</p>", "src": "Schultz, rozdz. 12", "k": ["relaksacja części ciała", "biofeedback: sprzężenie zwrotne", "modyfikacja: nagradzanie zachowań"], "u": "cwiczenia-2.html", "s": "s7"}, {"id": "praca/cwiczenia-2-fiszki:287a28fe", "q": "Jakie zmiany w miejscu pracy prowadzą według Maslach i Leitera do kryzysu wypalenia?", "a": "<p><strong>Mniej wartości</strong> (krótkoterminowe zyski, fuzje), <strong>ekonomia światowa</strong> (przenoszenie pracy, konkurencja, spadek płac), <strong>technologia</strong> (zastępuje ludzi i kontakty), <strong>redystrybucja władzy</strong> (słabe związki, mikrozarządzanie, delegowanie problemów bez władzy), <strong>wyobcowanie w korporacji</strong> (ogromne zarobki dyrektorów przy zwolnieniach).</p>", "src": "Maslach i Leiter, rozdz. 1", "k": ["mniej wartości", "globalizacja, technologia", "redystrybucja władzy", "wyobcowanie"], "u": "cwiczenia-2.html", "s": "s8"}, {"id": "praca/cwiczenia-2-fiszki:71f2f34c", "q": "Jakie są trzy wymiary wypalenia zawodowego według Maslach?", "a": "<p><strong>Wyczerpanie</strong> – nadmierne obciążenie emocjonalne i fizyczne, pierwsza reakcja na stres. <strong>Cynizm i depersonalizacja</strong> – chłodny, zdystansowany stosunek do pracy i ludzi jako ochrona przed wyczerpaniem. <strong>Brak skuteczności</strong> – poczucie nieprzystosowania i utrata wiary we własne możliwości. Ich przeciwieństwa to energia, zaangażowanie, skuteczność.</p>", "src": "Maslach i Leiter, rozdz. 1", "k": ["wyczerpanie", "cynizm, depersonalizacja", "brak skuteczności", "przeciwieństwa: energia, zaangażowanie, skuteczność"], "u": "cwiczenia-2.html", "s": "s8"}, {"id": "praca/cwiczenia-2-fiszki:bdf73ea6", "q": "Jakie sześć obszarów niedopasowania człowieka i pracy prowadzi do wypalenia?", "a": "<p>(1) <strong>Przeciążenie pracą</strong>, (2) <strong>brak kontroli</strong>, (3) <strong>brak nagrody</strong> (zwłaszcza wewnętrznej), (4) <strong>załamanie wspólnoty</strong> (izolacja, nierozwiązywany konflikt), (5) <strong>brak sprawiedliwości</strong> (szacunek, uczciwe oceny i awanse), (6) <strong>konflikt wartości</strong> (wymagania sprzeczne z zasadami lub misja sprzeczna z faktycznymi celami).</p>", "src": "Maslach i Leiter, rozdz. 1", "k": ["przeciążenie, brak kontroli", "brak nagrody", "załamanie wspólnoty, niesprawiedliwość", "konflikt wartości"], "u": "cwiczenia-2.html", "s": "s8"}, {"id": "praca/cwiczenia-2-fiszki:4a0b0503", "q": "Gdzie Maslach i Leiter widzą przyczynę wypalenia i jaką proponują receptę?", "a": "<p>Przyczyna leży w <strong>otoczeniu społecznym pracy</strong> – strukturze i funkcjonowaniu miejsca pracy – a nie w słabości jednostki. Wypalenie to barometr dysfunkcji społecznej w organizacji. Recepta: zmiana <strong>organizacji</strong>, <strong>prewencja</strong> zamiast terapii, budowanie <strong>zaangażowania</strong> w pracę, model zdrowej organizacji.</p>", "src": "Maslach i Leiter, rozdz. 1", "k": ["otoczenie społeczne, nie jednostka", "zmiana organizacji", "prewencja", "budowanie zaangażowania"], "u": "cwiczenia-2.html", "s": "s8"}, {"id": "praca/cwiczenia-2-fiszki:712c016f", "q": "Jakie trzy tematy powtarzają się w opisach wypalenia?", "a": "<p><strong>Stopniowa utrata zaangażowania</strong> (praca traci znaczenie), <strong>erozja emocji</strong> (entuzjazm i radość ustępują złości, lękowi i depresji), <strong>problem dopasowania</strong> człowieka i pracy (ludzie widzą kryzys osobisty, ale źródłem jest miejsce pracy). Wypalenie to proces narastania niedopasowania potrzeb osoby i wymagań pracy.</p>", "src": "Maslach i Leiter, rozdz. 2", "k": ["utrata zaangażowania", "erozja emocji", "problem dopasowania"], "u": "cwiczenia-2.html", "s": "s9"}, {"id": "praca/cwiczenia-2-fiszki:4d9c1f1a", "q": "Czego uczy przypadek Julii?", "a": "<p>Znakomita nauczycielka odchodzi z zawodu: wypalenie zaczęło się z pozycji <strong>siły i sukcesu</strong>, nie słabości. Wystąpiło 6 obszarów niedopasowania (przeciążenie, brak kontroli nad polityką szkoły, niska płaca, niesprawiedliwość, konflikty w gronie, konflikt wartości). Najwyższy koszt wypalenia to utrata najlepszych pracowników.</p>", "src": "Maslach i Leiter, rozdz. 2", "k": ["z pozycji siły", "6 obszarów niedopasowania", "utrata najlepszych"], "u": "cwiczenia-2.html", "s": "s9"}, {"id": "praca/cwiczenia-2-fiszki:2f278a11", "q": "Dlaczego emocje są kluczem do zrozumienia wypalenia?", "a": "<p>Emocje są <strong>wskaźnikiem i mediatorem</strong> przemiany zaangażowania w wypalenie. Frustracja i gniew prowadzą do cynizmu i szukania kozła ofiarnego, wrogość – do sabotażu, lęk – do gorszej pracy; brakuje emocji pozytywnych. Emocje są <strong>społeczne</strong>: wrogość rodzi wrogość, więc wypalenie jest zaraźliwe i tworzy spiralę.</p>", "src": "Maslach i Leiter, rozdz. 2", "k": ["wskaźnik i mediator", "gniew, wrogość, lęk", "brak emocji pozytywnych", "spirala, zaraźliwość"], "u": "cwiczenia-2.html", "s": "s9"}, {"id": "praca/cwiczenia-2-fiszki:e26946f7", "q": "Dlaczego obwinianie jednostki za wypalenie jest według autorów błędem? Czym jest efekt kaskadowy?", "a": "<p>Pogląd, że wypaleni są słabi, przewrażliwieni lub chorzy, ignoruje kontekst; przełożony przypisuje spadek wydajności lenistwu, a pracownik – okolicznościom. Wypalenie to <strong>problem zawodowy</strong>, nie wada charakteru. <strong>Efekt kaskadowy</strong>: cięcia na wyższych poziomach przenoszą presję w dół, aż do pracowników pierwszej linii, którzy są najbardziej narażeni.</p>", "src": "Maslach i Leiter, rozdz. 2", "k": ["ignorowanie kontekstu", "różne perspektywy szefa i pracownika", "problem zawodowy", "kaskada do pierwszej linii"], "u": "cwiczenia-2.html", "s": "s9"}, {"id": "praca/cwiczenia-2-fiszki:dcfb4053", "q": "Jakie trzy stany poznawcze motywują do pracy według Czerw i Czarnoty-Bojarskiej?", "a": "<p><strong>Dopasowanie człowiek–praca</strong> (P-J fit: kompetencje i cele a możliwości zawodu), <strong>dopasowanie człowiek–organizacja</strong> (P-O fit: warunki i wymagania miejsca pracy a oczekiwania pracownika) oraz <strong>postawa wobec pracy</strong> (subiektywna waga pracy). Im większe dopasowanie i bardziej pozytywna postawa, tym większa motywacja.</p>", "src": "Czerw i Czarnota-Bojarska (2016)", "k": ["P-J fit", "P-O fit", "postawa wobec pracy"], "u": "cwiczenia-2.html", "s": "s10"}, {"id": "praca/cwiczenia-2-fiszki:1879f40a", "q": "Czym różnią się atomistyczne, molekularne i molarne badanie dopasowania?", "a": "<p><strong>Atomistyczne</strong>: niezależny pomiar cech osoby i otoczenia i porównanie (pomija wagę rozbieżności). <strong>Molekularne</strong>: osoba opisuje siebie i otoczenie, porównuje się oba opisy (możliwy nietrafny ogląd otoczenia). <strong>Molarne</strong>: osoba wprost ocenia poczucie dopasowania (ocena ogólna zabarwia szczegółowe). Pełna ocena wymaga wszystkich trzech (Edwards i in.).</p>", "src": "Czerw i Czarnota-Bojarska (2016)", "k": ["atomistyczne: obiektywne porównanie", "molekularne: dwa opisy osoby", "molarne: wprost poczucie dopasowania"], "u": "cwiczenia-2.html", "s": "s10"}, {"id": "praca/cwiczenia-2-fiszki:488095af", "q": "Czym różni się dopasowanie suplementarne od komplementarnego i jak definiuje dopasowanie Kristof?", "a": "<p><strong>Suplementarne</strong>: podobieństwo celów i wartości pracownika i organizacji. <strong>Komplementarne</strong>: wzajemne uzupełnianie braków – „potrzeby–zasoby” (perspektywa pracownika) i „wymagania–możliwości” (perspektywa organizacji). <strong>Kristof</strong>: zgodność, gdy co najmniej jedna strona dostarcza tego, czego potrzebuje druga, gdy mają podobne cechy, lub oba naraz.</p>", "src": "Czerw i Czarnota-Bojarska (2016)", "k": ["suplementarne: podobieństwo", "komplementarne: uzupełnianie", "potrzeby–zasoby, wymagania–możliwości", "Kristof: integracja"], "u": "cwiczenia-2.html", "s": "s10"}, {"id": "praca/cwiczenia-2-fiszki:b254f9ff", "q": "Na czym polega model ASA Schneidera?", "a": "<p>Cele założycieli kształtują kulturę i strukturę organizacji, a te decydują, kogo organizacja <strong>przyciąga</strong> (attraction), <strong>wybiera</strong> (selection) i kto w niej <strong>zostaje</strong> (attrition). Skutek: organizacja zachowuje unikalność, a pracownicy z czasem stają się coraz bardziej podobni (<strong>homogenizacja</strong>).</p>", "src": "Czerw i Czarnota-Bojarska (2016)", "k": ["attraction", "selection", "attrition", "homogenizacja"], "u": "cwiczenia-2.html", "s": "s10"}, {"id": "praca/cwiczenia-2-fiszki:16a2a63e", "q": "Jakie postawy wobec pracy wyróżnia się w literaturze i czym różni się praca jako robota, kariera i powołanie?", "a": "<p>Postawy: <strong>instrumentalna</strong> (zaspokajanie potrzeb), <strong>autoteliczna</strong> (samorealizacja), <strong>punitywna</strong> (praca jako kara, trud), <strong>normatywna</strong> (obowiązek wobec społeczeństwa); także etyka pracy Webera. Wrzesniewski: <strong>robota</strong> – liczą się korzyści materialne; <strong>kariera</strong> – inwestowanie w awans i status; <strong>powołanie</strong> – praca nierozerwalna z życiem i wartościami, spełnienie.</p>", "src": "Czerw i Czarnota-Bojarska (2016)", "k": ["instrumentalna, autoteliczna", "punitywna, normatywna", "robota, kariera, powołanie"], "u": "cwiczenia-2.html", "s": "s11"}, {"id": "praca/cwiczenia-2-fiszki:6d37e8f3", "q": "Jakie są konsekwencje dopasowania człowiek–organizacja?", "a": "<p>Wyższa <strong>satysfakcja</strong> z pracy, większe <strong>zaangażowanie</strong> i <strong>przywiązanie</strong> do organizacji, mniejsza chęć odejścia, więcej <strong>zachowań obywatelskich</strong> (zwłaszcza przy dopasowaniu suplementarnym). Związek z <strong>wykonaniem pracy</strong> jest słaby lub niejednoznaczny. W Polsce ważniejsze jest dopasowanie norm i wartości niż potrzeb.</p>", "src": "Czerw i Czarnota-Bojarska (2016)", "k": ["satysfakcja, zaangażowanie", "przywiązanie, mniej odejść", "zachowania obywatelskie", "słaby związek z wykonaniem"], "u": "cwiczenia-2.html", "s": "s11"}, {"id": "praca/cwiczenia-2-fiszki:b7018a0f", "q": "Czym jest job crafting i jakie trzy rodzaje zmian obejmuje?", "a": "<p>„Przedefiniowanie pracy” (Wrzesniewski i Dutton): aktywne działania pracownika zmieniające sposób postrzegania pracy, by poprawić dopasowanie. Zmiany: <strong>zadań</strong> (nowe zadania), <strong>relacji</strong> (kontakty z inspirującymi osobami), <strong>postawy poznawczej</strong> (dostrzeganie wagi zadań). Skutki: większa satysfakcja i zaangażowanie, mniejsze wypalenie.</p>", "src": "Czerw i Czarnota-Bojarska (2016)", "k": ["redefiniowanie pracy", "zadania", "relacje", "postawa poznawcza"], "u": "cwiczenia-2.html", "s": "s11"}, {"id": "praca/cwiczenia-2-fiszki:4ad8da0e", "q": "Czym różni się hedonistyczny od eudajmonistycznego dobrostanu w pracy?", "a": "<p><strong>Hedonistyczny</strong>: emocje w pracy i satysfakcja z pracy (przyjemność, zadowolenie). <strong>Eudajmonistyczny</strong>: praca <strong>wartościowa</strong> – <strong>ważna</strong> (służy osobistym celom) i <strong>sensowna</strong> (ma pozaosobisty, logiczny cel). Dobrostan to więcej niż brak stresu czy wypalenia.</p>", "src": "Czerw (2017), rozdz. 3", "k": ["hedonistyczny: emocje i satysfakcja", "eudajmonistyczny: wartość pracy", "ważność i sensowność", "więcej niż brak ill-being"], "u": "cwiczenia-2.html", "s": "s12"}, {"id": "praca/cwiczenia-2-fiszki:343f72fd", "q": "Jak opisuje emocje w pracy model kołowy Warra?", "a": "<p>Emocje opisuje się na dwóch wymiarach: <strong>nieprzyjemność–przyjemność</strong> i <strong>rozluźnienie–napięcie</strong> (32 emocje w kole). Uproszczona skala (12 emocji) mierzy osie <strong>zalękniony–spokojny</strong> i <strong>przygnębiony–entuzjastyczny</strong>; oś niezadowolony–zadowolony mierzą skale satysfakcji. Model pomija emocje złożone (duma, wstyd, wina).</p>", "src": "Czerw (2017), rozdz. 3", "k": ["przyjemność × napięcie", "zalękniony–spokojny", "przygnębiony–entuzjastyczny", "brak emocji złożonych"], "u": "cwiczenia-2.html", "s": "s12"}, {"id": "praca/cwiczenia-2-fiszki:83a25eb9", "q": "Czym jest satysfakcja z pracy i od czego zależy?", "a": "<p>Postawa wobec pracy z aspektem poznawczym (ocena) i emocjonalnym (nastrój) (Zalewska). Zależy od cech pracy – <strong>model Hackmana i Oldhama</strong>: różnorodność umiejętności, tożsamość zadań, znaczenie zadań, autonomia, informacje zwrotne – oraz od cech pracownika i kultury. Suma ocen aspektów słabo koreluje z oceną ogólną (różne wagi).</p>", "src": "Czerw (2017), rozdz. 3", "k": ["poznawcza + emocjonalna", "Hackman i Oldham: 5 cech pracy", "cechy pracownika, kultura", "problem wag aspektów"], "u": "cwiczenia-2.html", "s": "s12"}, {"id": "praca/cwiczenia-2-fiszki:136b751e", "q": "Jak definiuje się zaangażowanie w pracę i od czego ono zależy?", "a": "<p>Schaufeli i Bakker: pozytywny stan umysłu – <strong>wigor</strong>, <strong>oddanie</strong>, <strong>absorpcja</strong> (pomiar: UWES); ujemnie związany z wypaleniem, ale odrębny. Maslach i Leiter: przeciwieństwo wypalenia (energia, zaabsorbowanie, skuteczność). Kahn: identyfikacja z rolą. Zależy od zasobów osobistych (proaktywność, optymizm) i organizacyjnych – <strong>model JD-R</strong> (wymagania vs zasoby pracy).</p>", "src": "Czerw (2017), rozdz. 3", "k": ["wigor, oddanie, absorpcja", "UWES", "odrębne od wypalenia", "JD-R: wymagania i zasoby"], "u": "cwiczenia-2.html", "s": "s12"}, {"id": "praca/wyklad-3-fiszki:a6ee4010", "q": "Co mówi cytat Stasiuk i Maison o „pierwszych lepszych” produktach w koszyku?", "a": "<p>Nawet gdy konsument nie przywiązuje wagi do zakupów, <strong>wybrał produkt spośród innych z jakiegoś powodu</strong>; dlatego zachowania konsumenckie bada się naukowo.</p>", "src": "Wykład 3: mechanizmy reklamy", "k": ["wybór zawsze ma jakiś powód", "uzasadnia naukowe badanie zachowań konsumenckich"], "u": "wyklad-3.html", "s": "s1"}, {"id": "praca/wyklad-3-fiszki:b7ece07b", "q": "Wymień pięć etapów decyzji w modelu EKB.", "a": "<p>(1) <strong>Rozpoznanie problemu</strong>, (2) <strong>poszukiwanie informacji</strong>, (3) <strong>ocena opcji</strong>, (4) <strong>decyzja zakupu</strong>, (5) <strong>ocena postdecyzyjna</strong> (Engel, Kollat, Blackwell, 1968).</p>", "src": "Wykład 3: mechanizmy reklamy", "k": ["rozpoznanie problemu", "poszukiwanie informacji", "ocena opcji", "decyzja zakupu", "ocena postdecyzyjna"], "u": "wyklad-3.html", "s": "s1"}, {"id": "praca/wyklad-3-fiszki:06d3215c", "q": "Jakie procesy psychologiczne odpowiadają etapom modelu EKB?", "a": "<p>Rozpoznanie problemu: <strong>motywacja</strong>; poszukiwanie informacji: <strong>percepcja</strong>; ocena opcji: <strong>formowanie postawy</strong>; decyzja: <strong>integracja informacji</strong>; ocena po zakupie: <strong>uczenie się</strong>.</p>", "src": "Wykład 3: mechanizmy reklamy", "k": ["motywacja", "percepcja", "formowanie postawy", "integracja informacji", "uczenie się"], "u": "wyklad-3.html", "s": "s1"}, {"id": "praca/wyklad-3-fiszki:8df42ae1", "q": "Jakie są źródła rozpoznania problemu w modelu EKB?", "a": "<p>Wyczerpanie zapasów (np. FMCG), brak satysfakcji („chcę nowszy model”), nowe potrzeby po zmianie sytuacji życiowej, najbliższe otoczenie („inni mają”).</p>", "src": "Wykład 3: mechanizmy reklamy", "k": ["wyczerpanie zapasów", "brak satysfakcji", "nowe potrzeby (zmiana sytuacji)", "otoczenie („inni mają”)"], "u": "wyklad-3.html", "s": "s1"}, {"id": "praca/wyklad-3-fiszki:805b18b5", "q": "Jakie źródła informacji wykorzystuje konsument w modelu EKB?", "a": "<p>Wewnętrzne: <strong>pamięć i wiedza</strong> o produktach. Zewnętrzne: internet, źródła <strong>osobiste</strong> (znajomi, rodzina, influencerzy, WoM), <strong>publiczne</strong> (niezależne opinie w prasie, TV), <strong>komercyjne</strong> (reklama).</p>", "src": "Wykład 3: mechanizmy reklamy", "k": ["wewnętrzne: pamięć i wiedza", "osobiste (znajomi, influencerzy)", "publiczne (niezależne opinie)", "komercyjne (reklama)"], "u": "wyklad-3.html", "s": "s1"}, {"id": "praca/wyklad-3-fiszki:70cd180e", "q": "Od czego zależy satysfakcja po zakupie w modelu EKB?", "a": "<p>Od <strong>oczekiwań przed zakupem</strong>; możliwy jest <strong>dysonans pozakupowy</strong>. To etap uczenia się.</p>", "src": "Wykład 3: mechanizmy reklamy", "k": ["oczekiwania przed zakupem", "dysonans pozakupowy"], "u": "wyklad-3.html", "s": "s1"}, {"id": "praca/wyklad-3-fiszki:b1444f81", "q": "Jakie pięć źródeł nieracjonalności konsumenta omawia wykład?", "a": "<p>(A) <strong>heurystyki</strong> i automatyzmy, (B) potrzeby, wartości, postawy, czyli <strong>motywacja</strong>, (C) <strong>postawy utajone</strong>, ukryta motywacja, metafory, (D) <strong>nastrój i emocje</strong>, (E) <strong>cechy osobowości</strong>.</p>", "src": "Wykład 3: mechanizmy reklamy", "k": ["heurystyki", "motywacja", "postawy utajone, metafory", "nastrój i emocje", "cechy osobowości"], "u": "wyklad-3.html", "s": "s2"}, {"id": "praca/wyklad-3-fiszki:937c00a7", "q": "Czym są heurystyki i jaką pełnią funkcję?", "a": "<p>Myśleniem „na skróty”: to <strong>ekonomia poznawcza</strong> i proces <strong>adaptacyjny</strong>, np. przy wyborze szamponu czy hotelu.</p>", "src": "Wykład 3: mechanizmy reklamy", "k": ["myślenie na skróty", "ekonomia poznawcza", "proces adaptacyjny"], "u": "wyklad-3.html", "s": "s2"}, {"id": "praca/wyklad-3-fiszki:68d47d7a", "q": "Na czym polega heurystyka reprezentatywności w wyborze konsumenckim? Podaj przykład.", "a": "<p>Decyzja opiera się na tym, w jakim stopniu produkt jest <strong>podobny</strong> do innych przypadków. Przykład: cenię szampony i żele marki X, więc odżywkę też wybieram marki X.</p>", "src": "Wykład 3: mechanizmy reklamy", "k": ["podobieństwo do innych przypadków", "przykład: ta sama marka w nowej kategorii"], "u": "wyklad-3.html", "s": "s2"}, {"id": "praca/wyklad-3-fiszki:0a6b8f21", "q": "Na czym polega heurystyka dostępności u konsumenta?", "a": "<p>Konsument opiera przewidywania na <strong>szybkości i łatwości</strong>, z jaką produkt <strong>przychodzi mu na myśl</strong> („jeżeli telefon, to marka…”).</p>", "src": "Wykład 3: mechanizmy reklamy", "k": ["szybkość i łatwość przypomnienia", "produkt przychodzi na myśl"], "u": "wyklad-3.html", "s": "s2"}, {"id": "praca/wyklad-3-fiszki:a1329fd2", "q": "Na czym polega heurystyka zakotwiczenia i dostosowania w zakupach?", "a": "<p>Najpierw <strong>osąd lub decyzja</strong>, potem <strong>racjonalizacja</strong> na podstawie dodatkowych informacji: po zakupie lodówki marki X szukam argumentów, że to dobry produkt.</p>", "src": "Wykład 3: mechanizmy reklamy", "k": ["najpierw osąd (decyzja)", "potem racjonalizacja"], "u": "wyklad-3.html", "s": "s2"}, {"id": "praca/wyklad-3-fiszki:03fe58d9", "q": "Jak Kotler (1994) definiuje marketing?", "a": "<p>Proces społeczny i zarządczy, dzięki któremu grupy otrzymują to, <strong>czego potrzebują i pragną</strong>, poprzez <strong>tworzenie, oferowanie i wymianę</strong> wartościowych produktów. Myślenie marketingowe zaczyna się od uświadomienia sobie potrzeb i pragnień.</p>", "src": "Wykład 3: mechanizmy reklamy", "k": ["proces społeczny i zarządczy", "potrzeby i pragnienia", "tworzenie, oferowanie, wymiana produktów"], "u": "wyklad-3.html", "s": "s3"}, {"id": "praca/wyklad-3-fiszki:d0b5c058", "q": "Czym są instynkt, wrodzony mechanizm wyzwalający i bodziec wyzwalający w etologii?", "a": "<p><strong>Instynkt</strong>: biologicznie ukształtowany, stereotypowy wzorzec zachowania z mechanizmem energetycznym. <strong>Wrodzony mechanizm wyzwalający</strong>: niewymagający uczenia się bodziec, konieczny i wystarczający do zachowania instynktownego. <strong>Bodziec wyzwalający</strong>: np. widok dziecka, partnera, jedzenia.</p>", "src": "Wykład 3: mechanizmy reklamy", "k": ["instynkt: stereotypowy wzorzec + energia", "mechanizm wyzwalający: bez uczenia się, konieczny i wystarczający", "bodziec: widok dziecka, partnera, jedzenia"], "u": "wyklad-3.html", "s": "s3"}, {"id": "praca/wyklad-3-fiszki:527a3b97", "q": "Jakie są etapy aktywności sterowanej instynktem?", "a": "<p>(1) <strong>narastanie instynktu</strong>, (2) etap <strong>apetytywny</strong>, (3) etap <strong>konsumacyjny</strong>.</p>", "src": "Wykład 3: mechanizmy reklamy", "k": ["narastanie instynktu", "etap apetytywny", "etap konsumacyjny"], "u": "wyklad-3.html", "s": "s3"}, {"id": "praca/wyklad-3-fiszki:73b41101", "q": "Na czym polega zasada podwójnej kwantyfikacji Lorenza?", "a": "<p>Zachowanie zależy jednocześnie od <strong>siły popędu</strong> i <strong>siły bodźca wyzwalającego</strong>. Słaby popęd wymaga silnego bodźca; bardzo silny popęd może wywołać zachowanie bez bodźca (<strong>aktywność jałowa</strong>).</p>", "src": "Wykład 3: mechanizmy reklamy", "k": ["siła popędu", "siła bodźca wyzwalającego", "słaby popęd wymaga silnego bodźca", "aktywność jałowa"], "u": "wyklad-3.html", "s": "s3"}, {"id": "praca/wyklad-3-fiszki:93e49a16", "q": "Co wynika z zasady podwójnej kwantyfikacji dla reklamy?", "a": "<p>Przy <strong>słabym popędzie</strong> reklama musi mocno pobudzać (stąd przekrzykiwanie się reklam i odwołania do potrzeb pierwotnych). Przy <strong>silnym popędzie</strong> bodziec może być słaby, a reklama odwołuje się do innych potrzeb (np. stowarzyszania się). Dwa bodźce naraz <strong>wzmacniają</strong> działanie.</p>", "src": "Wykład 3: mechanizmy reklamy", "k": ["słaby popęd: silny bodziec, przekrzykiwanie się", "silny popęd: odwołanie do innych potrzeb", "dwa bodźce wzmacniają działanie"], "u": "wyklad-3.html", "s": "s3"}, {"id": "praca/wyklad-3-fiszki:0dbd17d1", "q": "Dlaczego „sex sells” nie zawsze działa?", "a": "<p>Gdy produkt <strong>nie pasuje</strong> do przekazu, reklama jest nieskuteczna; bodziec seksualny <strong>przyciąga uwagę do siebie, a nie do produktu</strong>; reklamy są nim <strong>przesycone</strong>.</p>", "src": "Wykład 3: mechanizmy reklamy", "k": ["brak dopasowania do produktu", "uwaga na bodziec, nie na produkt", "przesycenie"], "u": "wyklad-3.html", "s": "s3"}, {"id": "praca/wyklad-3-fiszki:c111920f", "q": "Jakie są zalety i dwa zastrzeżenia odwołań do instynktów w reklamie?", "a": "<p>Zaleta: instynkty opierają się na <strong>mechanizmach wrodzonych</strong>, więc działają silnie i niezawodnie. Ale (1) odwołanie musi być <strong>dopasowane do produktu</strong>, inaczej uwaga skupia się na przekazie; (2) konsumenci często potrzebują <strong>bardziej wyrafinowanych przekazów</strong>.</p>", "src": "Wykład 3: mechanizmy reklamy", "k": ["wrodzone, silne i niezawodne", "musi pasować do produktu", "potrzeba bardziej wyrafinowanych przekazów"], "u": "wyklad-3.html", "s": "s3"}, {"id": "praca/wyklad-3-fiszki:0e77f1bb", "q": "Jaką rolę w działaniu przypisuje się nieświadomości (Edelman i Tononi)?", "a": "<p>Za <strong>inicjację</strong> działań odpowiada nieświadomość, a za ich <strong>realizację</strong> świadomość; nawyki, nieświadome wspomnienia, zamiary i oczekiwania kształtują świadome doświadczenie.</p>", "src": "Wykład 3: mechanizmy reklamy", "k": ["nieświadomość inicjuje działanie", "świadomość je realizuje"], "u": "wyklad-3.html", "s": "s4"}, {"id": "praca/wyklad-3-fiszki:3d530051", "q": "Opisz przykład Nescafe Instant.", "a": "<p>Kawa rozpuszczalna słabo się sprzedawała; w <strong>ankietach</strong> mówiono o złym smaku. <strong>Test projekcyjny</strong> pokazał, że kupujące ją kobiety postrzegano jako <strong>leniwe i niezorganizowane</strong>. Nowa reklama pokazała <strong>aktywną, zapracowaną kobietę</strong>, która dzięki kawie ma więcej czasu; był sukces rynkowy.</p>", "src": "Wykład 3: mechanizmy reklamy", "k": ["ankiety: zły smak", "test projekcyjny: kupujące leniwe", "nowa reklama: zapracowana kobieta", "sukces"], "u": "wyklad-3.html", "s": "s4"}, {"id": "praca/wyklad-3-fiszki:bad6cfce", "q": "Dlaczego warto badać metafory konsumentów (Zaltman)?", "a": "<p>Ujawniają procesy, których konsumenci <strong>nie wyrażą dosłownie</strong>; metafory <strong>ukierunkowują uwagę</strong>, wpływają na percepcję, nadają sens i wpływają na decyzje.</p>", "src": "Wykład 3: mechanizmy reklamy", "k": ["ujawniają to, czego nie da się powiedzieć dosłownie", "ukierunkowują uwagę i percepcję", "wpływają na decyzje"], "u": "wyklad-3.html", "s": "s4"}, {"id": "praca/wyklad-3-fiszki:e094140f", "q": "Czym jest mapa konsensusu?", "a": "<p>Metafory istnieją w mózgu jako <strong>sieci abstrakcyjnych znaczeń</strong>; gdy są <strong>wspólne dla wielu osób</strong>, tworzą mapę konsensusu (Zaltman). Przykład: Chevrolet jako skała: niezawodny, mocny.</p>", "src": "Wykład 3: mechanizmy reklamy", "k": ["sieci abstrakcyjnych znaczeń", "wspólne dla wielu osób", "przykład: Chevrolet – skała"], "u": "wyklad-3.html", "s": "s4"}, {"id": "praca/wyklad-3-fiszki:f6022229", "q": "Na czym polega przypominanie zgodne z nastrojem (Bower)?", "a": "<p>Nastrój jest <strong>wskazówką pamięciową</strong>: łatwiej przypominamy sobie treści zgodne z nastrojem z czasu zapamiętywania. Badani w dobrym nastroju utożsamiali się z wesołym bohaterem i później przypominali sobie więcej jego cech, w złym ze smutnym.</p>", "src": "Wykład 3: mechanizmy reklamy", "k": ["nastrój jako wskazówka pamięciowa", "łatwiej treści zgodne z nastrojem", "badanie z wesołym i smutnym bohaterem"], "u": "wyklad-3.html", "s": "s5"}, {"id": "praca/wyklad-3-fiszki:4250293f", "q": "Na co wpływa nastrój pozytywny w zachowaniach konsumenckich?", "a": "<p>Sprzyja <strong>uleganiu perswazji</strong>, decyzjom <strong>ryzykownym</strong>, wydawaniu <strong>większych sum</strong> i <strong>zakupom impulsywnym</strong>.</p>", "src": "Wykład 3: mechanizmy reklamy", "k": ["uleganie perswazji", "decyzje ryzykowne", "większe wydatki", "zakupy impulsywne"], "u": "wyklad-3.html", "s": "s5"}, {"id": "praca/wyklad-3-fiszki:2d52570d", "q": "Czym różni się przetwarzanie reklamy w nastroju pozytywnym i negatywnym?", "a": "<p>Pozytywny: myślenie <strong>elastyczne, twórcze</strong>, szeroki obszar sieci, ale przetwarzanie <strong>powierzchowne</strong>. Negatywny: <strong>czujność</strong>, wąski obszar sieci, przetwarzanie <strong>głębokie</strong>.</p>", "src": "Wykład 3: mechanizmy reklamy", "k": ["pozytywny: elastyczne, szerokie", "pozytywny: powierzchowne", "negatywny: czujność, wąskie", "negatywny: głębokie"], "u": "wyklad-3.html", "s": "s5"}, {"id": "praca/wyklad-3-fiszki:dc7e7c90", "q": "Jakie czynniki indywidualne i sytuacyjne wpływają na wybory konsumenckie i do czego się to wykorzystuje?", "a": "<p>Motywy i potrzeby, <strong>temperament i osobowość</strong>, <strong>wartości</strong>, środowisko i czynniki sytuacyjne; wykorzystuje się je w <strong>segmentacji rynku</strong> i <strong>mikrotargetowaniu</strong>.</p>", "src": "Wykład 3: mechanizmy reklamy", "k": ["temperament i osobowość", "wartości, środowisko, sytuacja", "segmentacja i mikrotargetowanie"], "u": "wyklad-3.html", "s": "s5"}, {"id": "praca/wyklad-3-fiszki:cb5969b1", "q": "Wymień pięć podejść do skuteczności reklamy.", "a": "<p><strong>Naiwne</strong> (jest wszechobecna i droga), <strong>ekonomiczne</strong> (wydatki korelują ze sprzedażą), <strong>mediów</strong> (zasięg w grupie docelowej), <strong>twórcze</strong> (dobrze zrobiona, kreatywna), <strong>psychologiczne</strong> (działanie na poziomie indywidualnym).</p>", "src": "Wykład 3: mechanizmy reklamy", "k": ["naiwne", "ekonomiczne", "mediów", "twórcze", "psychologiczne"], "u": "wyklad-3.html", "s": "s6"}, {"id": "praca/wyklad-3-fiszki:eb103b37", "q": "Czym podejście psychologiczne do skuteczności reklamy różni się od pozostałych?", "a": "<p>Ustala działanie reklamy na <strong>poziomie indywidualnym</strong>: bada związki między <strong>konkretnymi bodźcami w reklamie</strong> a <strong>reakcjami konsumentów</strong> (Fennis i Stroebe, 2010).</p>", "src": "Wykład 3: mechanizmy reklamy", "k": ["poziom indywidualny", "bodźce w reklamie", "reakcje konsumentów"], "u": "wyklad-3.html", "s": "s6"}, {"id": "praca/wyklad-3-fiszki:e0b351b9", "q": "Na czym polega iluzja odporności na reklamy (Duck i Mullin)?", "a": "<p>Ludzie sądzą, że media mają <strong>większy wpływ na innych</strong> niż na nich samych.</p>", "src": "Wykład 3: mechanizmy reklamy", "k": ["media wpływają bardziej na innych", "nie na mnie"], "u": "wyklad-3.html", "s": "s7"}, {"id": "praca/wyklad-3-fiszki:bf75ee6b", "q": "Dlaczego nietrafnie oceniamy własną podatność na reklamę?", "a": "<p>Chcemy widzieć siebie <strong>lepszymi</strong> i wierzyć w pomyślną przyszłość; widzenie siebie jako <strong>niezależnego</strong> umacnia <strong>poczucie własnej wartości</strong>; przeceniamy cechy społecznie pożądane.</p>", "src": "Wykład 3: mechanizmy reklamy", "k": ["chcemy widzieć siebie lepszymi", "niezależność", "poczucie własnej wartości"], "u": "wyklad-3.html", "s": "s7"}, {"id": "praca/wyklad-3-fiszki:4744120a", "q": "Jakie dwa mechanizmy podtrzymują iluzję odporności na reklamy?", "a": "<p><strong>Racjonalizacja</strong> („ona kupuje pod wpływem reklamy, a ja na spróbowanie”) i <strong>pamięć źródła informacji</strong>: pamiętamy treść, ale nie to, że pochodzi z reklamy (Johnson i in., 1993).</p>", "src": "Wykład 3: mechanizmy reklamy", "k": ["racjonalizacja", "pamięć źródła (source monitoring)"], "u": "wyklad-3.html", "s": "s7"}, {"id": "praca/wyklad-3-fiszki:5daabc20", "q": "Jak Aaker (1991) definiuje wartość marki?", "a": "<p>Zestaw <strong>aktywów i zobowiązań</strong> (cech) powiązanych z marką, jej nazwą i symbolem, które <strong>dodają lub odejmują wartość</strong> produktu lub usługi.</p>", "src": "Wykład 3: mechanizmy reklamy", "k": ["aktywa i zobowiązania marki", "powiązane z nazwą i symbolem", "dodają lub odejmują wartość"], "u": "wyklad-3.html", "s": "s8"}, {"id": "praca/wyklad-3-fiszki:1b4aaa81", "q": "Wymień platformy współpracy marek tworzące wspólną wartość marki.", "a": "<p>Sponsoring, udział <strong>celebrytów</strong>, udział <strong>influencerów</strong>, <strong>lokowanie produktu</strong>, <strong>co-branding</strong>, człowiek jako marka, marketing terytorialny (Cornwell i in., 2022).</p>", "src": "Wykład 3: mechanizmy reklamy", "k": ["sponsoring", "celebryci i influencerzy", "lokowanie produktu", "co-branding", "human branding i place branding"], "u": "wyklad-3.html", "s": "s8"}, {"id": "praca/wyklad-3-fiszki:918f335c", "q": "Czym jest współdzielona wartość marki?", "a": "<p>Stopniem, w jakim <strong>wiedza semantyczna i skojarzeniowa</strong> między markami jest powiązana, <strong>szeroko reprezentowana w społeczności językowej</strong> i wpływa na reakcje na markę (oczekiwania, poglądy, decyzje).</p>", "src": "Wykład 3: mechanizmy reklamy", "k": ["powiązana wiedza skojarzeniowa marek", "reprezentowana w społeczności", "wpływa na reakcje na markę"], "u": "wyklad-3.html", "s": "s8"}, {"id": "praca/wyklad-3-fiszki:aa2db965", "q": "Jakie fazy ma model budowania współdzielonej wartości marki (Cornwell i in.)?", "a": "<p>(1) <strong>Rozpoczęcie partnerstwa</strong>: nakładające się skojarzenia partnerów; (2) <strong>rozwój wspólnej wartości</strong>: działania budujące i osłabiające, moderowane czasem trwania i zdarzeniami afektywnymi; (3) <strong>kontynuacja albo zakończenie</strong>, po którym zostaje <strong>rezydualna</strong> wspólna wartość.</p>", "src": "Wykład 3: mechanizmy reklamy", "k": ["rozpoczęcie: nakładające się skojarzenia", "rozwój: działania budujące i osłabiające", "zakończenie: wartość rezydualna"], "u": "wyklad-3.html", "s": "s8"}, {"id": "praca/wyklad-3-fiszki:812f1d5b", "q": "Co zakłada sieciowy model pamięci Andersona (1983)?", "a": "<p>Jednostki poznawcze (<strong>węzły</strong>) tworzą <strong>sieć</strong>, a połączenia między nimi mają <strong>różną siłę</strong>.</p>", "src": "Wykład 3: mechanizmy reklamy", "k": ["węzły tworzą sieć", "połączenia o różnej sile"], "u": "wyklad-3.html", "s": "s9"}, {"id": "praca/wyklad-3-fiszki:ead12a8e", "q": "Kiedy według modeli sieciowych marka jest silna?", "a": "<p>Gdy ma <strong>silne, liczne i pozytywne</strong> skojarzenia.</p>", "src": "Wykład 3: mechanizmy reklamy", "k": ["silne", "liczne", "pozytywne"], "u": "wyklad-3.html", "s": "s9"}, {"id": "praca/wyklad-3-fiszki:eabb70e4", "q": "Jakie znaczenie dla reklamy mają przenoszenie i wspólne skojarzenia?", "a": "<p><strong>Przenoszenie skojarzeń</strong> może służyć <strong>nieuczciwej konkurencji</strong>; <strong>wspólne skojarzenia</strong> dają <strong>wzajemne wzmacnianie</strong> marek współpracujących; rozbudowa sieci w kampaniach wpływa na świadomość konsumencką.</p>", "src": "Wykład 3: mechanizmy reklamy", "k": ["przenoszenie: nieuczciwa konkurencja", "wspólne: wzajemne wzmacnianie", "rozbudowa sieci a świadomość konsumencka"], "u": "wyklad-3.html", "s": "s9"}, {"id": "praca/wyklad-3-fiszki:087ea61f", "q": "Co pokazuje przykład sieci skojarzeń z Coca-Colą?", "a": "<p>Marka ma węzły <strong>negatywne</strong> (niezdrowa, chemia, choroba) i <strong>pozytywne</strong> (radość, ekscytacja, rodzina, święta, Mikołaj). Kampanie <strong>wzmacniają pozytywne węzły</strong> i ich połączenia z marką.</p>", "src": "Wykład 3: mechanizmy reklamy", "k": ["węzły negatywne", "węzły pozytywne (radość, święta)", "kampanie wzmacniają pozytywne"], "u": "wyklad-3.html", "s": "s9"}, {"id": "praca/wyklad-3-fiszki:6b4d5171", "q": "Czym różni się co-branding od co-marketingu?", "a": "<p><strong>Co-branding</strong>: marki łączą potencjał i tworzą <strong>wspólny produkt</strong> (np. ONLYBIO × E.Wedel). <strong>Co-marketing</strong>: wspólne działania marketingowe <strong>bez nowego produktu</strong> (np. Disney i Delta).</p>", "src": "Wykład 3: mechanizmy reklamy", "k": ["co-branding: wspólny produkt", "co-marketing: wspólne działania bez produktu"], "u": "wyklad-3.html", "s": "s10"}, {"id": "praca/wyklad-3-fiszki:c392e4c1", "q": "Jak w badaniu spójności marek mierzono siłę i podobieństwo skojarzeń?", "a": "<p>Siła zależy od <strong>pozycji skojarzenia</strong> (pierwsze najsilniejsze; Szalay i Deese). Podobieństwo liczono <strong>modelem proporcji Tverskiego</strong>: siła wspólnych skojarzeń przez sumę sił skojarzeń obu marek (Iga i Oshee: 264 / (431 + 391) = 0,32).</p>", "src": "Wykład 3: mechanizmy reklamy", "k": ["siła wg pozycji skojarzenia", "model proporcji Tverskiego", "wspólne przez sumę obu marek"], "u": "wyklad-3.html", "s": "s10"}, {"id": "praca/wyklad-3-fiszki:7e7e380d", "q": "Jakie wnioski płyną z badań reklam łączących markę z osobą znaną lub inną marką?", "a": "<p>Marki <strong>przenoszą skojarzenia</strong> (i afekt) między sobą; trzeba <strong>kontrolować siłę i rodzaj</strong> skojarzeń; wspólna reklama nie zawsze służy obu markom (np. Semilac z Wedlem oceniany jako mniej stabilny).</p>", "src": "Wykład 3: mechanizmy reklamy", "k": ["przenoszenie skojarzeń i afektu", "kontrola siły i rodzaju skojarzeń", "nie zawsze korzystne dla obu"], "u": "wyklad-3.html", "s": "s10"}, {"id": "praca/wyklad-3-fiszki:0faa1f77", "q": "Czym jest reklama natywna?", "a": "<p>Płatna reklama <strong>wtopiona w treść</strong> platformy: spójna z jej treścią, układem i stylem, przez co odbiorca uważa, że do niej <strong>należy</strong>; nie jest inwazyjna.</p>", "src": "Wykład 3: mechanizmy reklamy", "k": ["płatna reklama wtopiona w treść", "wygląda jak część platformy", "nieinwazyjna"], "u": "wyklad-3.html", "s": "s11"}, {"id": "praca/wyklad-3-fiszki:c04a7ca9", "q": "Co dzieje się, gdy konsument rozpozna reklamę natywną?", "a": "<p>Uruchamia się <strong>wiedza o perswazji</strong>; spada <strong>wiarygodność</strong> i nastawienie do marki, ale rośnie <strong>chęć podzielenia się</strong> treścią. Wraz ze wzrostem wiedzy o reklamie natywnej jej <strong>efektywność spada</strong>.</p>", "src": "Wykład 3: mechanizmy reklamy", "k": ["model wiedzy o perswazji", "spadek wiarygodności", "większa chęć dzielenia się", "skuteczność spada z wiedzą"], "u": "wyklad-3.html", "s": "s11"}, {"id": "praca/wyklad-3-fiszki:08bde8d9", "q": "Jaki odsetek osób nie rozpoznaje reklam natywnych w mediach społecznościowych?", "a": "<p><strong>56%</strong> (Boerman i Kruikemeier, 2016); ponad 30% nigdy nie zauważyło oznaczenia reklamy.</p>", "src": "Wykład 3: mechanizmy reklamy", "k": ["56%"], "u": "wyklad-3.html", "s": "s11"}];
